/**
 * @survscribe/types -- the shared TypeScript view of the SurvScribe API v1 contract.
 *
 * `schema.d.ts` is generated by `openapi-typescript` from
 * `documentation/architecture/api-contract/openapi.yaml`, which is itself generated from
 * the migration DDL. Nothing in this package is hand-maintained except this file, which
 * exists only to give the generated shapes names worth importing: `components["schemas"]
 * ["AssessmentLineItem"]` is accurate but nobody wants to read it at a call site.
 *
 * Regenerate with `pnpm --filter @survscribe/types generate`. Never edit `schema.d.ts`.
 */
import type { components, operations, paths } from "./schema";

export type { components, operations, paths };

type Schemas = components["schemas"];

/* ------------------------------------------------------------------ envelopes */

/** ADR-0004 section 2. Every successful response has this shape. */
export interface ApiSuccess<T> {
  success: true;
  data: T;
  error: null;
  meta: Schemas["Meta"] | null;
}

/** ADR-0004 section 3. */
export type ApiErrorBody = Schemas["ErrorResponse"];
export type ApiError = Schemas["ApiError"];
export type ErrorCode = Schemas["ErrorCode"];
export type Meta = Schemas["Meta"];

export type ApiResponse<T> = ApiSuccess<T> | ApiErrorBody;

export function isApiError<T>(r: ApiResponse<T>): r is ApiErrorBody {
  return r.success === false;
}

/**
 * A rupee amount. Every NUMERIC crosses the wire as a decimal string, never a JSON
 * number: IEEE-754 cannot hold NUMERIC(15,2) exactly, and FR-15.1 gate 1 requires the
 * Section F totals to reconcile to the rupee. Do not `parseFloat` these for arithmetic --
 * use the deterministic decimal engine.
 */
export type Decimal = string;

