/* ------------------------------------------------------------------ constants */

/** The 15 workflow stages. `claims.current_stage` is 1-15 (FR-1.3, CR-W1). */
export const STAGE_MIN = 1;
export const STAGE_MAX = 15;

/**
 * The four points of the Human Approval Gate (FR-14.4). All four must be recorded before
 * a PSR or FSR `.docx` can be generated -- see CLAUDE.md section 14 constraint 4.
 */
export const APPROVAL_GATE_POINTS = [
  "reviewed_ai_content",
  "confirmed_factual_accuracy",
  "confirmed_calculations",
  "accepted_professional_responsibility",
] as const;

/** The seven Stage 15 compliance gates, in FR-15.1 order (D36). */
export const AUDIT_GATES = [
  "ARITHMETIC_CHECK",
  "METADATA_CONSISTENCY",
  "DEDUCTION_REMARKS",
  "PHOTO_ANNEXURE_COMPLIANCE",
  "DOCUMENT_COMPLETENESS",
  "CONTRADICTION_SCANNER",
  "HUMAN_APPROVAL_AI_GATE",
] as const;

/** Placeholder AI-4 must emit instead of inventing a fact (CLAUDE.md section 14 constraint 3). */
export const SURVEYOR_TO_VERIFY = "[SURVEYOR TO VERIFY]";
